mapper.select:
select p.id,p.number,p.supplier_id,sup.name supplier_name,p.amount_cents,p.threshold_exceeded,p.status,p.current_node,
       p.creator_id,p.creation_key,p.revision,p.remark,p.review_comment,p.director_comment,p.create_time,p.update_time
from payments p left join suppliers sup on sup.document_id=p.supplier_id
where p.deleted='0'
and p.id=#{id}
and exists(select 1 from sys_user cu where cu.user_id=p.creator_id and cu.dept_id=#{params.supplyScopeDeptId} and cu.del_flag='0')
and p.creator_id=#{params.supplyScopeUserId}
and p.number like concat('%',#{number},'%')
and p.supplier_id=#{supplierId}
and p.status=#{status}
and p.status='IN_REVIEW'
order by p.update_time desc

mapper.update:
update payments set status=#{status},current_node=#{node},revision=revision+1,update_time=#{updateTime}
,review_comment=#{reviewComment}
,director_comment=#{directorComment}
where id=#{id} and revision=#{revision} and deleted='0'
